package world

import (
	"fmt"

	"mcgo/block"
)

const (
	ChunkSizeX = 16
	ChunkSizeY = 64
	ChunkSizeZ = 16
)

// ChunkPos identifies a chunk in the world
type ChunkPos struct {
	X, Z int
}

func (cp ChunkPos) String() string {
	return fmt.Sprintf("(%d,%d)", cp.X, cp.Z)
}

// Chunk stores blocks as a flat array [y][z][x]
type Chunk struct {
	Pos    ChunkPos
	Blocks [ChunkSizeY][ChunkSizeZ][ChunkSizeX]block.BlockType
	Dirty  bool // set to true when blocks change, triggers mesh rebuild
}

// NewChunk creates an empty chunk filled with air
func NewChunk(pos ChunkPos) *Chunk {
	c := &Chunk{Pos: pos, Dirty: true}
	for y := 0; y < ChunkSizeY; y++ {
		for z := 0; z < ChunkSizeZ; z++ {
			for x := 0; x < ChunkSizeX; x++ {
				c.Blocks[y][z][x] = block.Air
			}
		}
	}
	return c
}

// GetBlock returns the block at local chunk coordinates
func (c *Chunk) GetBlock(x, y, z int) block.BlockType {
	if x < 0 || x >= ChunkSizeX || y < 0 || y >= ChunkSizeY || z < 0 || z >= ChunkSizeZ {
		return block.Air
	}
	return c.Blocks[y][z][x]
}

// SetBlock sets a block at local chunk coordinates
func (c *Chunk) SetBlock(x, y, z int, bt block.BlockType) {
	if x < 0 || x >= ChunkSizeX || y < 0 || y >= ChunkSizeY || z < 0 || z >= ChunkSizeZ {
		return
	}
	c.Blocks[y][z][x] = bt
	c.Dirty = true
}

// FillLayer sets an entire y-layer to a block type
func (c *Chunk) FillLayer(y int, bt block.BlockType) {
	if y < 0 || y >= ChunkSizeY {
		return
	}
	for z := 0; z < ChunkSizeZ; z++ {
		for x := 0; x < ChunkSizeX; x++ {
			c.Blocks[y][z][x] = bt
		}
	}
	c.Dirty = true
}

// WorldToChunk converts world coordinates to chunk position and local coordinates
func WorldToChunk(wx, wy, wz int) (ChunkPos, int, int, int) {
	cx := wx >> 4 // floor division by 16 for positive
	cz := wz >> 4
	if wx < 0 {
		cx = (wx - 15) >> 4
	}
	if wz < 0 {
		cz = (wz - 15) >> 4
	}
	lx := wx - cx*ChunkSizeX
	lz := wz - cz*ChunkSizeZ
	if lx < 0 {
		lx += ChunkSizeX
		cx--
	}
	if lz < 0 {
		lz += ChunkSizeZ
		cz--
	}
	return ChunkPos{cx, cz}, lx, wy, lz
}

package world

import (
	"math"
	"math/rand"
)

// Perlin noise implementation
type PerlinNoise struct {
	perm [512]int
}

func NewPerlinNoise(seed int64) *PerlinNoise {
	p := &PerlinNoise{}
	rng := rand.New(rand.NewSource(seed))
	var ptable [256]int
	for i := 0; i < 256; i++ {
		ptable[i] = i
	}
	for i := 255; i > 0; i-- {
		j := rng.Intn(i + 1)
		ptable[i], ptable[j] = ptable[j], ptable[i]
	}
	for i := 0; i < 256; i++ {
		p.perm[i] = int(ptable[i])
		p.perm[i+256] = int(ptable[i])
	}
	return p
}

func fade(t float64) float64 { return t * t * t * (t*(t*6-15) + 10) }
func lerp(t, a, b float64) float64 { return a + t*(b-a) }
func grad(hash int, x, y, z float64) float64 {
	h := hash & 15
	var u, v float64
	if h < 8 {
		u = x
	} else {
		u = y
	}
	if h < 4 {
		v = y
	} else if h == 12 || h == 14 {
		v = x
	} else {
		v = z
	}
	if h&1 == 0 {
		u = -u
	}
	if h&2 == 0 {
		v = -v
	}
	return u + v
}

func (p *PerlinNoise) Noise3D(x, y, z float64) float64 {
	X := int(math.Floor(x)) & 255
	Y := int(math.Floor(y)) & 255
	Z := int(math.Floor(z)) & 255
	xf := x - math.Floor(x)
	yf := y - math.Floor(y)
	zf := z - math.Floor(z)
	u := fade(xf)
	v := fade(yf)
	w := fade(zf)
	aaa := p.perm[p.perm[p.perm[X]+Y]+Z]
	aba := p.perm[p.perm[p.perm[X]+Y+1]+Z]
	aab := p.perm[p.perm[p.perm[X]+Y]+Z+1]
	abb := p.perm[p.perm[p.perm[X]+Y+1]+Z+1]
	baa := p.perm[p.perm[p.perm[X+1]+Y]+Z]
	bba := p.perm[p.perm[p.perm[X+1]+Y+1]+Z]
	bab := p.perm[p.perm[p.perm[X+1]+Y]+Z+1]
	bbb := p.perm[p.perm[p.perm[X+1]+Y+1]+Z+1]
	x1 := lerp(u, grad(aaa, xf, yf, zf), grad(baa, xf-1, yf, zf))
	x2 := lerp(u, grad(aba, xf, yf-1, zf), grad(bba, xf-1, yf-1, zf))
	y1 := lerp(v, x1, x2)
	x3 := lerp(u, grad(aab, xf, yf, zf-1), grad(bab, xf-1, yf, zf-1))
	x4 := lerp(u, grad(abb, xf, yf-1, zf-1), grad(bbb, xf-1, yf-1, zf-1))
	y2 := lerp(v, x3, x4)
	return lerp(w, y1, y2)
}

// OctavePerlin produces higher-detail terrain using multiple octaves
func (p *PerlinNoise) OctavePerlin(x, y, z float64, octaves int, persistence float64) float64 {
	var total float64
	var maxVal float64
	amp := 1.0
	freq := 1.0
	for i := 0; i < octaves; i++ {
		total += p.Noise3D(x*freq, y*freq, z*freq) * amp
		maxVal += amp
		amp *= persistence
		freq *= 2.0
	}
	return total / maxVal
}

// HeightAt returns terrain height (surface Y) at given (x,z) world coordinates
func (p *PerlinNoise) HeightAt(wx, wz int) int {
	// Use 2D noise (by using constant Z=0 in 3D noise) with multiple octaves
	const (
		scale     = 0.03
		baseLevel = 32
		hillAmp   = 24
	)
	nx := float64(wx) * scale
	nz := float64(wz) * scale
	val := p.OctavePerlin(nx, 0, nz, 4, 0.5)
	// val is roughly in [-1, 1]
	height := baseLevel + int(math.Round(val*hillAmp))
	if height < 1 {
		height = 1
	}
	if height > 60 {
		height = 60
	}
	return height
}

package world

import (
	"math/rand"
	"sync"

	"mcgo/block"
)

// World holds all chunks and provides terrain generation
type World struct {
	mu       sync.RWMutex
	chunks   map[ChunkPos]*Chunk
	generator *PerlinNoise
	seaLevel int
}

// NewWorld creates a new world with a random seed
func NewWorld() *World {
	seed := rand.Int63()
	return NewWorldWithSeed(seed)
}

// NewWorldWithSeed creates a world with a specific seed
func NewWorldWithSeed(seed int64) *World {
	return &World{
		chunks:   make(map[ChunkPos]*Chunk),
		generator: NewPerlinNoise(seed),
		seaLevel: 32,
	}
}

// GetChunk returns a chunk, generating it if not yet loaded
func (w *World) GetChunk(pos ChunkPos) *Chunk {
	w.mu.RLock()
	c, ok := w.chunks[pos]
	w.mu.RUnlock()
	if ok {
		return c
	}
	return w.GenerateChunk(pos)
}

// GenerateChunk creates a new chunk with terrain
func (w *World) GenerateChunk(pos ChunkPos) *Chunk {
	w.mu.Lock()
	defer w.mu.Unlock()
	// Double-check after acquiring write lock
	if c, ok := w.chunks[pos]; ok {
		return c
	}
	c := NewChunk(pos)
	baseX := pos.X * ChunkSizeX
	baseZ := pos.Z * ChunkSizeZ

	for lx := 0; lx < ChunkSizeX; lx++ {
		for lz := 0; lz < ChunkSizeZ; lz++ {
			wx := baseX + lx
			wz := baseZ + lz
			height := w.generator.HeightAt(wx, wz)
			for ly := 0; ly < ChunkSizeY; ly++ {
				wy := ly
				var bt block.BlockType
				if wy == 0 {
					bt = block.Stone // bedrock
				} else if wy < height-4 {
					bt = block.Stone
				} else if wy < height-1 {
					bt = block.Dirt
				} else if wy == height-1 {
					bt = block.Grass
				} else if wy <= w.seaLevel {
					bt = block.Water
				} else {
					bt = block.Air
				}
				c.Blocks[ly][lz][lx] = bt
			}
		}
	}

	// Add some trees on grass blocks
	for lx := 2; lx < ChunkSizeX-2; lx += 4 {
		for lz := 2; lz < ChunkSizeZ-2; lz += 4 {
			wx := baseX + lx
			wz := baseZ + lz
			height := w.generator.HeightAt(wx, wz)
			if height < 34 && height >= 30 {
				// Only place trees on grass that's above water
				if c.GetBlock(lx, height-1, lz) == block.Grass {
					placeTree(c, lx, height, lz)
				}
			}
		}
	}

	c.Dirty = true
	w.chunks[pos] = c
	return c
}

func placeTree(c *Chunk, trunkX, trunkY, trunkZ int) {
	// Trunk: 4 blocks tall
	trunkHeight := 4
	for dy := 0; dy < trunkHeight; dy++ {
		if trunkY+dy < ChunkSizeY {
			c.SetBlock(trunkX, trunkY+dy, trunkZ, block.Wood)
		}
	}
	// Leaves: 3x3x2 canopy starting at trunkY+trunkHeight-2
	leafStart := trunkY + trunkHeight - 2
	for dy := 0; dy < 3; dy++ {
		y := leafStart + dy
		if y >= ChunkSizeY {
			break
		}
		radius := 2
		if dy == 0 || dy == 2 {
			radius = 1
		}
		for dx := -radius; dx <= radius; dx++ {
			for dz := -radius; dz <= radius; dz++ {
				if dx == 0 && dz == 0 && dy < 2 {
					continue // don't replace trunk
				}
				// Make leaves not perfectly full
				if dx*dx+dz*dz > radius*radius {
					continue
				}
				cx := trunkX + dx
				cz := trunkZ + dz
				if cx >= 0 && cx < ChunkSizeX && cz >= 0 && cz < ChunkSizeZ {
					if c.GetBlock(cx, y, cz) == block.Air || c.GetBlock(cx, y, cz) == block.Leaves {
						c.SetBlock(cx, y, cz, block.Leaves)
					}
				}
			}
		}
	}
}

// GetBlock returns the block at world coordinates
func (w *World) GetBlock(wx, wy, wz int) block.BlockType {
	if wy < 0 || wy >= ChunkSizeY {
		return block.Air
	}
	pos, lx, _, lz := WorldToChunk(wx, wy, wz)
	c := w.GetChunk(pos)
	return c.GetBlock(lx, wy, lz)
}

// SetBlock sets a block at world coordinates and marks the chunk dirty
func (w *World) SetBlock(wx, wy, wz int, bt block.BlockType) {
	if wy < 0 || wy >= ChunkSizeY {
		return
	}
	pos, lx, _, lz := WorldToChunk(wx, wy, wz)
	c := w.GetChunk(pos)
	c.SetBlock(lx, wy, lz, bt)
}

// GetLoadedChunks returns all currently loaded chunks
func (w *World) GetLoadedChunks() []*Chunk {
	w.mu.RLock()
	defer w.mu.RUnlock()
	result := make([]*Chunk, 0, len(w.chunks))
	for _, c := range w.chunks {
		result = append(result, c)
	}
	return result
}

// LoadRadius ensures chunks within a radius of the player are generated
func (w *World) LoadRadius(cx, cz, radius int) {
	for dx := -radius; dx <= radius; dx++ {
		for dz := -radius; dz <= radius; dz++ {
			pos := ChunkPos{cx + dx, cz + dz}
			w.GetChunk(pos)
		}
	}
}
